95.     /// - `block_size`: Size of blocks in bytes.
96.     ///
97.     /// # Returns
98.     ///
99.     /// Upon success, a new slab allocator is returned. Upon failure, an error is returned instead
100.     /// and the memory may be left in an modified state.
101.     ///
102.     /// # Safety
103.     ///
104.     /// This function is unsafe for the following reasons:
105.     /// - It assumes that the memory region starting at `addr` with `len` bytes is valid.
106.     ///
107.     #[verus_spec(result =>
108.          ensures
109.              match result {
110.                  Ok(slab) => {
111.                      &&& slab.inv()
112.                      &&& slab@.block_size == block_size
113.                      &&& slab@.start_addr >= addr as usize
114.                      &&& slab@.end_addr <= addr as usize + len
115.                      &&& slab@.allocated_addrs == Set::<usize>::empty()
116.                      &&& forall|i: int| 0 <= i < (slab@.end_addr - slab@.start_addr) / block_size as int
117.                          ==> #[trigger] slab@.free_addrs.contains(
118.                              (slab@.start_addr + i * block_size as int) as usize)
119.                  },
120.                  Err(e) => {
121.                      &&& e.code == ErrorCode::InvalidArgument
122.                      &&& {
123.                          ||| addr as usize == 0
124.                          ||| len == 0
125.                          ||| len >= i32::MAX
126.                          ||| len > isize::MAX
127.                          ||| addr as usize + len > usize::MAX
128.                          ||| block_size == 0
129.                          ||| block_size >= i32::MAX
130.                          ||| block_size > (usize::MAX - 1) / (u8::BITS as int)
131.                          ||| len < block_size * 2
132.                          ||| addr as usize % block_size != 0
133.                      }
134.                  }
135.              },
136.     )]
137.     pub unsafe fn from_raw_parts(
138.         addr: *mut u8,
139.         len: usize,
140.         block_size: usize,
141.     ) -> Result<Slab, Error> {
142.         // Make sure the address isn't null, e.g., from a failed allocation.
143.         if addr.is_null() {
144.             return Err(Error::new(ErrorCode::InvalidArgument, "null pointer"));
145.         }
146. 
147.         // Check if length is invalid.
148.         if len == 0 || len >= i32::MAX as usize || len > isize::MAX as usize {
149.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid slab length"));
150.         }
151. 
152.         // Check if the memory region wraps around.
153.         proof! { Self::lemma_wrapping_add_consequences(addr, len); }
154.         if addr.wrapping_add(len) < addr {
155.             return Err(Error::new(ErrorCode::InvalidArgument, "wrapping memory region"));
156.         }
157. 
158.         // Check if the block size is valid.
159.         // TODO: Make this `const U8_BITS` instead of `let u8_bits` once issue
160.         // https://github.com/verus-lang/verus/issues/2023 is fixed.
161.         let u8_bits: usize = u8::BITS as usize;
162.         if block_size == 0
163.             || block_size >= i32::MAX as usize
164.             || block_size > (usize::MAX - 1) / u8_bits
165.             || block_size > len
166.         {
167.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid block size"));
168.         }
169. 
170.         // Check if `addr` is aligned to `block_size`.
171.         if !(addr as usize).is_multiple_of(block_size) {
172.             return Err(Error::new(ErrorCode::InvalidArgument, "unaligned start address"));
173.         }
174. 
175.         // Compute layout of the slab allocator.
176.         let total_num_blocks: usize = len / block_size;
177. 
178.         // The number of index blocks (`num_index_blocks`) we need is
179.         //  `ceil(total_num_blocks / (block_size * u8::BITS + 1))`
180.         // for the following reason. This condition implies:
181.         //  `num_index_blocks * (block_size * u8::BITS + 1) >= total_num_blocks`
182.         // This, in turn, implies that:
183.         //  `num_index_blocks * block_size * u8::BITS  >= total_num_blocks - num_index_blocks`
184.         // The left-hand side of this inequality is the number of bits that
185.         // `num_index_blocks` blocks contain. The right-hand side of this inequality
186.         // is the number of blocks that aren't index blocks. So, a bitmap occupying
187.         // `num_index_blocks` blocks can address all the blocks outside of that bitmap.
188.         let divisor: usize = block_size * u8_bits + 1;
189.         let num_index_blocks: usize = (total_num_blocks / divisor)
190.             + if total_num_blocks.is_multiple_of(divisor) {
191.                 0
192.             } else {
193.                 1
194.             };
195.         if num_index_blocks >= total_num_blocks {
196.             proof! {
197.                 Self::lemma_no_room_for_index(len, block_size, total_num_blocks,
198.                                               num_index_blocks, divisor);
199.             }
200.             return Err(Error::new(ErrorCode::InvalidArgument, "insufficient blocks for index"));
201.         }
202. 
203.         proof! {
204.             Slab::lemma_can_compute_data_addr(addr, total_num_blocks, num_index_blocks,
205.                                               block_size, len);
206.         }
207.         let data_addr: *mut u8 = addr.add(num_index_blocks * block_size);
208. 
209.         let num_data_blocks: usize = total_num_blocks - num_index_blocks;
210.         let index_len: usize = (num_data_blocks / u8_bits)
211.             + if num_data_blocks.is_multiple_of(u8_bits) {
212.                 0
213.             } else {
214.                 1
215.             };
216. 
217.         // Instantiate index.
218.         proof! {
219.             Slab::lemma_can_create_raw_array(addr, total_num_blocks, num_index_blocks,
220.                                              num_data_blocks, block_size, len, index_len);
221.         }
222.         let storage: RawArray<u8> = RawArray::from_raw_parts(addr, index_len)?;
223. 
224.         proof! {
225.             assert forall|i| 0 <= i < index_len implies storage@[i] == 0 by {
226.                 raw_array::axiom_u8_zero_is_0(storage@[i]);
227.             }
228.         }
229.         let mut index: Bitmap = Bitmap::from_raw_array(storage)?;
230. 
231.         // NOTE: The index is initialized with all blocks free, thus if we fail beyond this point
232.         // the memory region is left in a modified state.
233. 
234.         // Initialize index.
235.         //
236.         // The uppermost bits of the index may point beyond the end of
237.         // the allocated region. So, we need to set those bits to mark
238.         // them "in use" and thereby prevent them from being
239.         // allocated. Note that there are at most 7 such bits we need
240.         // to set.
241.         #[cfg_attr(verus_keep_ghost, verus_spec(
242.             invariant
243.                 index.inv(),
244.                 index@.num_bits == index_len * u8_bits,
245.                 index@.set_bits == Set::new(|j: int| num_data_blocks <= j < i),
246.         ))]
247.         for i in num_data_blocks..(index_len * u8_bits) {
248.             index.set(i)?;
249.         }
250. 
251.         let end_addr = addr.add(total_num_blocks * block_size);
252.         proof! {
253.             Slab::lemma_from_raw_parts_establishes_inv(
254.                 block_size, data_addr, end_addr, &index,
255.                 addr, len, total_num_blocks, num_index_blocks,
256.                 num_data_blocks, index_len, u8_bits,
257.             );
258.         }
259.         Ok(Slab {
260.             index,
261.             data_addr,
262.             end_addr,
263.             block_size,
264.         })
265.     }
266. 
267.     ///
268.     /// # Description
269.     ///
270.     /// Allocates a block of memory from the slab allocator.
271.     ///
272.     /// # Returns
273.     ///
274.     /// Upon success, a pointer to the allocated block is returned. Upon failure, an error is
275.     /// returned instead.
276.     ///
277.     #[verus_spec(result =>
278.         requires
279.             old(self).inv(),
280.         ensures
281.             final(self).inv(),
282.             match result {
283.                 Ok(ptr) => {
284.                     let addr = ptr as usize;
285.                     &&& old(self)@.free_addrs.contains(addr)
286.                     &&& addr % final(self)@.block_size == 0
287.                     &&& final(self)@ == SlabView {
288.                         allocated_addrs: old(self)@.allocated_addrs.insert(addr),
289.                         free_addrs: old(self)@.free_addrs.remove(addr),
290.                         ..old(self)@
291.                     }
292.                 },
293.                 Err(_) => {
294.                     &&& old(self)@.free_addrs == Set::<usize>::empty()
295.                     &&& final(self)@ == old(self)@
296.                 },
297.             },
298.     )]
299.     pub fn allocate(&mut self) -> Result<*mut u8, Error> {
300.         let block: usize = self.index.alloc()?;
301. 
302.         proof! { self.lemma_allocate_add_is_safe(block); }
303.         let block_addr: *mut u8 = unsafe { self.data_addr.add(block * self.block_size) };
304. 
305.         proof! { self.lemma_allocate_ok(old(self), block, block_addr as usize); }
306. 
307.         Ok(block_addr)
308.     }
309. 
310.     ///
311.     /// # Description
312.     ///
313.     /// Frees a block of memory from the slab allocator.
314.     ///
315.     /// # Parameters
316.     ///
317.     /// - `ptr`: Pointer to the block to free.
318.     ///
319.     /// # Returns
320.     ///
321.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
322.     ///
323.     /// # Safety
324.     ///
325.     /// This function is unsafe for the following reasons:
326.     ///
327.     /// - It uses `offset_from_unsigned`.
328.     ///
329.     #[verus_spec(result =>
330.         requires
331.             old(self).inv(),
332.         ensures
333.             final(self).inv(),
334.             match result {
335.                 Ok(()) => {
336.                     &&& old(self)@.allocated_addrs.contains(ptr as usize)
337.                     &&& final(self)@ == (SlabView {
338.                         allocated_addrs: old(self)@.allocated_addrs.remove(ptr as usize),
339.                         free_addrs: old(self)@.free_addrs.insert(ptr as usize),
340.                         ..old(self)@
341.                     })
342.                 },
343.                 Err(_) => {
344.                     &&& !old(self)@.allocated_addrs.contains(ptr as usize)
345.                     &&& final(self)@ == old(self)@
346.                 },
347.             },
348.     )]
349.     pub unsafe fn deallocate(&mut self, ptr: *const u8) -> Result<(), Error> {
350.         // Return an error if the pointer is before or after the data blocks.
351.         if ptr < self.data_addr as *const u8 || ptr >= self.end_addr {
352.             return Err(Error::new(ErrorCode::BadAddress, "pointer out of bounds"));
353.         }
354. 
355.         // Return an error if the pointer isn't at a block boundary.
356.         if !(ptr as usize).is_multiple_of(self.block_size) {
357.             return Err(Error::new(ErrorCode::BadAddress, "pointer unaligned"));
358.         }
359. 
360.         proof! { self.lemma_deallocate_offset_bound(ptr); }

